"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[9861],{49861:a=>{a.exports=JSON.parse('{"meta":{"title":"Skill Alexa Muslim Companion: Azan di Echo Anda - iMuslim Life","description":"Muslim Companion memainkan azan di Amazon Echo anda pada waktu solat anda, bersama al-Quran, zikir, Hifz Coach dan mod Ramadan. Percuma. Tetapkan di alexa.imuslimlife.com."},"hero":{"title":"Muslim Companion untuk Alexa","lede":"Azan pada waktu solat tempatan anda, zikir selepas solat, bacaan al-Quran dan peringatan daripada masjid anda, di Amazon Echo anda.","live":"\u2714 Kini di Alexa","dashboard":"Buka Papan Pemuka","tryWeb":"Cuba Aplikasi Web","imgAlt":"Peranti Amazon Alexa","athan":"\\"Allahu Akbar...\\"","maghrib":"Maghrib pada 7:45 malam"},"how":{"h2":"Cara Ia Berfungsi","sub":"Sediakan muazin peribadi anda dalam tiga langkah mudah, kurang daripada lima minit.","s1":{"h3":"Dayakan Skill","p":"Buka aplikasi Alexa di telefon anda, cari <b>Muslim Companion</b> dan ketik <i>Enable to Use</i>. Kemudian sebut dalam bahasa Inggeris \\"<q>{{p1}}</q>\\" (Alexa, buka Muslim Companion) untuk mengesahkan."},"s2":{"h3":"Log Masuk & Tetapkan","p":"Lawati <a>alexa.imuslimlife.com</a>, log masuk, sahkan lokasi anda, pilih suara azan dan ikuti masjid anda (contohnya AMCC) untuk peringatan iqamah dan Jumaat.","voice":"<b>Atau dengan suara:</b> \\"<q>{{p1}}</q>\\" (tetapkan kaedah pengiraan kepada ISNA) dan \\"<q>{{p2}}</q>\\" (tetapkan mazhab kepada Hanafi), tanpa papan pemuka. Lihat arahan suara di bawah."},"s3":{"h3":"Cipta Rutin & Nikmati","p":"Dalam aplikasi Alexa, cipta satu rutin: apabila sensor <i>Muslim Companion Azan</i> terbuka, buka <i>Muslim Companion</i>. Echo anda kemudian memainkan azan secara automatik pada setiap waktu solat. <a>Panduan persediaan langkah demi langkah</a> kami membimbing anda dengan tangkapan skrin."}},"features":{"h2":"Ciri Utama","sub":"Semuanya ditetapkan di alexa.imuslimlife.com, dan setiap ciri tambahan dimatikan sehingga anda menghidupkannya","soon":"Akan datang: semakan ulama","items":{"athan":{"title":"Azan pada waktu solat anda","description":"Echo anda memainkan azan pada waktu tempatan untuk kelima-lima solat, dengan pilihan suara muazin dan azan khas Subuh."},"masjid":{"title":"Masjid Connect","description":"Ikuti masjid anda (seperti AMCC) dan dapatkan peringatan sebelum setiap iqamah dan sebelum Jumaat, mengikut waktu yang diterbitkan masjid."},"quran":{"title":"Bacaan al-Quran","description":"Lebih 30 qari terkenal. Satu surah selepas azan, atau al-Quran dimainkan sepanjang hari, dan sambung dari tempat anda berhenti."},"adhkar":{"title":"Zikir selepas solat","description":"Ayat al-Kursi dan tiga Qul selepas setiap solat, dengan teks Arab dan terjemahan Inggeris atau Urdu. Dimatikan sehingga anda menghidupkannya."},"hifz":{"title":"Hifz Coach","description":"Hafal beberapa ayat sekali gus di Echo anda: setiap ayat tiga kali, kemudian seluruh pelajaran bersama, dengan kemajuan disimpan. Berlatih dalam talian juga."},"ramadan":{"title":"Mod Ramadan","description":"Peringatan sahur sebelum Subuh, pengumuman berbuka pada Maghrib, dan bacaan tarawih Makkah selepas Isyak."},"show":{"title":"Skrin Echo Show","description":"Waktu solat hari ini di skrin dengan solat seterusnya diserlahkan dan kiraan detik, serta widget Waktu Solat yang sentiasa dipaparkan."},"scenes":{"title":"Suasana Rumah","description":"Malapkan lampu ketika azan, bangun perlahan sebelum Subuh, atau wujudkan malam yang tenang selepas Isyak, dengan rutin Alexa anda sendiri."},"duas":{"title":"Doa selepas azan","description":"Doa selepas azan dan doa pilihan anda, dimainkan di Echo sejurus selepas azan."},"qibla":{"title":"Arah kiblat","description":"Tanya arah kiblat: arah dari rumah anda dalam darjah dan arah kompas, serta jarak ke Makkah."},"hijri":{"title":"Tarikh Hijrah & kalendar Islam","description":"Tarikh Hijrah hari ini, dan berapa hari lagi ke Ramadan, Hari Raya, Asyura, Arafah atau hari-hari putih. Tarikh yang sama dengan waktu solat anda."},"fasting":{"title":"Puasa sunat","description":"Tanya bila puasa sunat seterusnya, atau dapatkan peringatan selepas Isyak pada malam sebelum Isnin, Khamis, hari-hari putih, Arafah dan Asyura."},"tasbih":{"title":"Tasbih & zikir pagi dan petang","description":"Alexa mengira zikir bersama anda (33, 33, 34 selepas solat), dengan pembilang sentuh di Echo Show, dan memainkan zikir pagi dan petang."},"translation":{"title":"Al-Quran dengan terjemahan","description":"Mainkan mana-mana surah dengan suara, dengan terjemahan Inggeris atau Urdu selepas setiap ayat, dan Surah Al-Kahf setiap Jumaat."},"daily":{"title":"Doa, Hadis & Nama-nama Allah harian","description":"Satu doa ringkas, hadis atau salah satu daripada 99 Nama setiap hari, dengan sumbernya, disemak ulama sebelum diterbitkan."}}},"screens":{"h2":"Lihat ia berfungsi","sub":"Skrin sebenar sebuah keluarga yang mengikuti AMCC di Florida: waktu solat untuk lokasi mereka sendiri, dan waktu iqamah yang diterbitkan masjid.","showAlt":"Skrin Echo Show: waktu solat hari ini dengan iqamah masjid, dan solat seterusnya, Maghrib, diserlahkan dengan kiraan detik","showH":"Di Echo Show anda","showP":"Sebut \\"<q>{{p1}}</q>\\" (tanya Muslim Companion waktu solat hari ini): lima waktu solat dan syuruk, iqamah masjid anda di sebelah setiap satu, dan solat seterusnya diserlahkan dengan kiraan detik.","phoneAlt":"Masjid Saya di telefon: masjid, waktu azan dan iqamah hari ini, Jumaat, dan pilihan peringatan Echo","phoneH":"Di telefon anda","phoneP":"Di <a>alexa.imuslimlife.com</a>, buka <b>Masjid Saya</b> dan pilih masjid anda. Anda melihat waktu azan dan iqamah hari ini dan Jumaat minggu ini, dan memilih bila Echo mengingatkan anda sebelum iqamah dan Jumaat.","widgetAlt":"Widget Waktu Solat: solat seterusnya Maghrib dengan kiraan detik, waktu iqamah dan lima waktu solat hari ini","widgetH":"Widget sentiasa dipaparkan","widgetP":"Di Echo Show 8, 10 dan 15, tambah widget <b>Waktu Solat</b>: solat seterusnya, kiraan detiknya dan iqamah masjid anda kekal di skrin utama."},"voice":{"h2":"Arahan Suara","sub":"Semua yang boleh anda sebut kepada Muslim Companion, dikumpulkan mengikut ciri. Menggunakan pembantu AI? <a>Sambungkannya ke waktu solat kami</a>."},"ref":{"langsTitle":"Bahasa dan negara","langsBody":"Muslim Companion memahami bahasa <b>Inggeris</b>, <b>Arab</b> (\\"\u0627\u0644\u0631\u0641\u064a\u0642 \u0627\u0644\u0645\u0633\u0644\u0645\\") dan <b>Hindi</b> (\\"\u092e\u0941\u0938\u094d\u0932\u093f\u092e \u0915\u092e\u094d\u092a\u0948\u0928\u093f\u092f\u0928\\"). Dalam bahasa Inggeris, sebut frasa tepat seperti yang ditulis, bermula dengan \\"<q>{{p1}}</q>\\" (namanya sama di <b>Amerika Syarikat, Kanada, United Kingdom, India dan Australia</b>). Pilih bahasa di atas untuk melihat frasa Arab atau Hindi. Jika frasa mempunyai pilihan, seperti kaedah pengiraan, penerangan menyenaraikan setiap pilihan.","soonNote":"Arahan bertanda <b>Akan datang</b> belum tersedia; lencana menerangkan sebabnya.","english":"English","soonSuffix":" \xb7 akan datang","langNote":"<b>{{title}}</b>: tetapkan bahasa Alexa kepada {{lang}} untuk menggunakan Muslim Companion dalam bahasa itu. Nama skill dalam bahasa ini ialah <n>{{name}}</n>. Inilah frasa tepat yang difahaminya; penerangan kekal dalam bahasa Inggeris.","langAr":"Arab (Arab Saudi)","langHi":"Hindi (India)","all":"Semua","comingSoon":"Akan datang","showsOnShow":"Dipaparkan di Echo Show","whilePlaying":"Semasa Muslim Companion dimainkan","turnsOff":"Mematikan azan automatik","tip":"Petua: {{tip}}","footer":"Anda juga boleh mula dengan \\"<q>{{p1}}</q>\\" (Alexa, buka Muslim Companion) dan kemudian bertanya. Arahan seperti \\"<q>next</q>\\" (seterusnya), \\"<q>pause</q>\\" (jeda) dan \\"<q>stop</q>\\" (henti) berfungsi semasa Muslim Companion dimainkan."},"api":{"h2":"Dikuasakan oleh API Kami yang Teruji","p":"Skill Alexa Muslim Companion dibina di atas API waktu solat kami yang mantap, dengan pengiraan tepat berdasarkan lokasi sebenar anda.","methods":{"primary":"23 Kaedah Pengiraan + Asar Hanafi atau Standard","secondary":"ISNA, Liga Muslim Sedunia, Umm al-Qura, Mesir, Karachi, Teluk, Kuwait, Qatar, Singapura, Perancis, Turki, Rusia, Tehran dan Jafari, ditetapkan di papan pemuka atau dengan suara"},"hijri":{"primary":"Integrasi Kalendar Hijrah","secondary":"Tarikh Islam yang tepat bersama waktu solat"},"perf":{"primary":"Prestasi Tinggi","secondary":"Dioptimumkan untuk kelajuan dan kebolehpercayaan"},"free":{"primary":"Percuma untuk Komuniti","secondary":"API waktu solat percuma digunakan"},"cta":"Teroka API Kami","imgAlt":"Ilustrasi API"},"cta":{"h2":"Sedia mendengar azan daripada Alexa?","p":"Skill kini tersedia. Tetapkan jadual solat peribadi anda dalam masa kurang lima minit.","guide":"Lihat Panduan Persediaan","small":"Percuma selamanya \xb7 Tiada muat turun aplikasi \xb7 Berfungsi dengan semua peranti Echo"},"faq":{"h2":"Soalan Lazim","devices":{"q":"Peranti Alexa mana yang disokong skill ini?","a":"Skill Muslim Companion berfungsi dengan mana-mana peranti Amazon Echo atau peranti yang menyokong Alexa. Untuk bunyi terbaik, kami mengesyorkan peranti dengan pembesar suara berkualiti seperti Echo, Echo Dot atau Echo Show."},"dst":{"q":"Adakah skill menyesuaikan diri dengan waktu jimat siang secara automatik?","a":"Ya, skill menyesuaikan waktu solat secara automatik mengikut zon waktu lokasi anda dan perubahan waktu jimat siang. Anda sentiasa mendapat waktu tepat tanpa sebarang pelarasan manual."},"choose":{"q":"Bolehkah saya memilih solat mana yang memainkan azan?","a":"Sudah tentu! Anda boleh memilih solat mana yang memainkan azan, contohnya hanya Subuh, Maghrib dan Isyak, atau kelima-lima solat. Pilih di halaman Tetapan Solat di alexa.imuslimlife.com."},"cost":{"q":"Adakah skill ini berbayar?","a":"Skill Muslim Companion percuma sepenuhnya. Fungsi terasnya, waktu solat yang tepat dan azan automatik, kekal percuma untuk komuniti Muslim, selamanya."},"offline":{"q":"Bagaimana jika sambungan internet terputus?","a":"Waktu solat anda dikira lebih awal, tetapi Echo memerlukan internet untuk memainkan azan. Jika sambungan terputus pada waktu solat, azan itu mungkin terlepas; semuanya bersambung semula secara automatik apabila talian pulih."}},"films":{"eyebrow":"Lihat sendiri","title":"Sediakan Muslim Companion dalam masa kurang seminit","athan":{"tab":"Azan setiap waktu solat","length":"1 min","play":"Mainkan video persediaan azan","p1":"Dayakan skill","p2":"Alexa menemui sensor","p3":"Cipta rutin","cta":"Buka papan pemuka","after":"Selepas rutin disimpan, lengkapkan persediaan: log masuk di alexa.imuslimlife.com, atau buka aplikasi Salat-e-Mustaqeem dan ketik ikon Alexa."},"quran":{"tab":"Al-Quran selepas setiap azan","length":"40 saat","play":"Mainkan video persediaan jadual Al-Quran","p1":"Qari pilihan anda","p2":"Surah pertama anda","p3":"Al-Kahfi pada hari Jumaat","badge":"Strim 24/7 di Alexa","after":"Pilih qari, surah permulaan dan apa yang dimainkan seterusnya. Azan seterusnya sentiasa didahulukan, jadi bacaan tidak pernah memasuki waktu solat.","cta":"Sediakan jadual Al-Quran"}},"widgets":{"soon":"Akan datang","h3":"Lapan widget baharu untuk Echo Show","sub":"Pilih rupa yang anda suka untuk skrin utama. Widget ini sedang disemak oleh Amazon dan akan muncul dalam galeri widget Echo Show anda sebaik sahaja diluluskan.","items":{"mihrab":{"name":"Tingkap mihrab","desc":"Solat seterusnya dalam bingkai tingkap melengkung, bersama kiraan detiknya.","alt":"Widget Tingkap mihrab untuk Echo Show"},"sun-arc":{"name":"Lengkung matahari","desc":"Matahari bergerak sepanjang hari dari Subuh hingga Isyak, jadi anda tahu kedudukan anda sepintas lalu.","alt":"Widget Lengkung matahari untuk Echo Show"},"lamps":{"name":"Lima pelita","desc":"Satu pelita bagi setiap solat; pelita solat seterusnya bercahaya keemasan.","alt":"Widget Lima pelita untuk Echo Show"},"illuminated":{"name":"Halaman iluminasi","desc":"Solat seterusnya dalam khat Arab keemasan, pada halaman bergaya manuskrip.","alt":"Widget Halaman iluminasi untuk Echo Show"},"timetable":{"name":"Jadual bercetak","desc":"Kelima-lima solat dalam jadual bercetak yang kemas, dengan solat seterusnya ditanda.","alt":"Widget Jadual bercetak untuk Echo Show"},"ink-arch":{"name":"Gerbang dakwat","desc":"Gerbang lukisan dakwat di sekeliling solat seterusnya dan kiraan detiknya.","alt":"Widget Gerbang dakwat untuk Echo Show"},"ayah":{"name":"Ayat Hari Ini","desc":"Ayat baharu setiap hari dalam bahasa Arab bersama maknanya dalam bahasa Inggeris (Saheeh International).","alt":"Widget Ayat Hari Ini untuk Echo Show"},"now-reciting":{"name":"Sedang Dibaca","desc":"Surah dan qari yang dimainkan pada Echo anda, terus di skrin utama.","alt":"Widget Sedang Dibaca untuk Echo Show"}},"readAlongH":"Baca bersama Mushaf","readAlongP":"Turut disemak: ikuti bacaan pada halaman Mushaf di Echo Show, setiap perkataan diserlahkan semasa dibaca. Ketik perkataan untuk pergi ke ayatnya."}}')}}]);